K.say(S,{kind:'sys',tag:'来店',text:introT,why:'目標：'+h.goal.label+'／'+h.action.label+(TR?'／施術者は住人の'+TR.name+(o.picked?'（住人の欄で選んだ）':'（住人から）')+(plain?'。'+whyP:hardTop?'。受け攻めでは客の'+h.name+'が主導する側':''):mobNG?'／'+whyP:'')});
K.snap(S,{s:0});
