function shiftTxt(t2){if(tierShown<0||t2<=tierShown){tierShown=Math.max(tierShown,t2);return'';}tierShown=t2;return LV.SHIFT&&LV.SHIFT[t2]?K.fmt(S,fresh(S,LV.SHIFT[t2]))+' ':'';}
