var osw=say(S,{kind:'climax',tag:'甘イキが止まらない',text:K.fmt(S,LV.sweetText(sp,topMe)),why:'感覚が戻ったあと、激しくされて '+(nC+r.climaxes.length)+'回続けて果てた（絶頂 '+h.climax+'回目まで）'});
