if(kind==='pair'||kind==='gone'){var tf=PO?PO.isF(t):t.gender==='f',bf=PO?PO.isFBody(b):b.gender==='f';key=kind+(tf&&bf?'FF':tf?'FM':'M');}
var l=VA.THICK_ERO[key];
