sayV({kind:'phase',text:'深夜のお色気バラエティ「'+show+'」、生放送スタート！　'+mc+'の呼び込みで、'+P.map(function(p){return p.name;}).join('・')+'がスタジオに登場した。'+(VA.MC_OPEN?mc+pkv(VA.MC_OPEN):'')});
