if(rel==='mutual'&&LK.MUT)lines.push(ST.fmt(pk(LK.MUT.end[outcome==='bed'||heldNo||(pair.acts>=1&&outcome!=='angry'&&outcome!=='plotfail')?'told':'miss']),v0));
